{
  "distSpecVersion": "1.1.0",
  "storage": {
    "rootDirectory": "/var/lib/registry",
    "gc": true,
    "dedupe": true
  },
  "http": {
    "address": "0.0.0.0",
    "port": "5000",
    "auth": {
      "htpasswd": {
        "path": "/etc/zot/htpasswd"
      }
    }
  },
  "extensions": {
    "search": { "enable": true },
    "lint": { "enable": true },
    "scrub": { "enable": true, "interval": "24h" },
    "mgmt": { "enable": true }
  },
  "log": { "level": "info" }
}
